import{z as A,x as l,o as s,c as d,q as r,j as i,D as e,d as t,s as n,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"EUV 剂量预算","description":"","frontmatter":{"title":"EUV 剂量预算","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-dose-budget.md","filePath":"litho/euv-dose-budget.md","lastUpdated":1791063341000}'),p={name:"litho/euv-dose-budget.md"};function m(h,E,D,c,u,g){const o=l("Mermaid");return s(),d("div",null,[E[2]||(E[2]=r('<h1 id="euv-剂量预算" tabindex="-1">EUV 剂量预算 <a class="header-anchor" href="#euv-剂量预算" aria-label="Permalink to &quot;EUV 剂量预算&quot;">​</a></h1><div class="epigraph"><p>EUV 的每一份剂量都是钱和缺陷的汇率：光子少一枚随机缺陷就冒头，光子多一档产能就掉一截——剂量预算是 stochastics 时代的中央账本。</p><footer>—— 据 EUV 光子统计（Poisson 噪声）；ASML NXE 剂量-产能表；imec stochastics 研究</footer></div><p><a href="/litho/wafer-edge-exclusion">晶圆边缘排除区</a>留出了物理余量，本课把余量折成光子：<strong>剂量预算</strong>。EUV 在 13.5nm 的光子能量高、数量少，散粒噪声让「同一剂量、不同晶圆点」的成像随机起伏成为先进节点的头号缺陷源。缺口是把剂量当预算管理：下限由缺陷率定、上限由产能定。本课不做 resist 化学的全貌。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>剂量（mJ/cm²）= 光子通量 × 时间。EUV 光子能量 92 eV，30 mJ/cm² 对应约 2×10¹² 光子/cm²——听着多，摊到一条 20nm 线的横截面上只有数百个光子，Poisson 涨落 ±√N 约 5%。光子少 → 胶响应随机 → 线边缘粗糙度（LER）与断线/桥连（stochastic defects）抬头；光子多 → 曝光时间延长，产能（wph）线性下降。缺口：<strong>在缺陷率、CD 控制与产能之间给剂量定价</strong>。</p><p><span class="marginnote">术语翻译：dose-to-size = 恰好印出目标 CD 的剂量；dose margin = 从 dose-to-size 到线塌/桥连的窗口；photon shot noise = 光子到达的泊松涨落，σ=√N；LER/LWR = 线边缘/线宽粗糙度。</span></p><p><span class="marginnote">数字实例：剂量 30→60 mJ/cm²（翻倍），单个特征的光子数翻倍、相对涨落从 ±5.8% 降到 ±4.1%——断线缺陷率可降一个量级；但单 wafer 曝光时间近似翻倍，产能从 175 wph 掉到 ~90 wph。一层换一层，年产能差出数亿美元——这就是「预算」的含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算管理四步：<strong>定下限</strong>——按目标缺陷率（dppm）反推所需剂量：胶灵敏度、量子效率与目标 CD 共同决定「光子泊松涨落不致命」的底线，imec 的高 NA 研究给出 20-25nm 特征需要 60+ mJ/cm² 的量级；<strong>定上限</strong>——产能合同与扫描时间约束；<strong>中间分配</strong>——PEB 放大（化学放大胶的酸扩散相当于「光子增益」）与 source-mask 优化把每一份剂量用在刀刃上；<strong>监控</strong>——在线剂量计量与 LER 抽测联动，剂量漂移即报警。</p>',9)),(s(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9B%AE%E6%A0%87%E7%BC%BA%E9%99%B7%E7%8E%87%20dppm%22%5D%20--%3E%20B%5B%22%E5%8F%8D%E6%8E%A8%E5%89%82%E9%87%8F%E4%B8%8B%E9%99%90%22%5D%0A%20%20C%5B%22%E4%BA%A7%E8%83%BD%E5%90%88%E5%90%8C%20wph%22%5D%20--%3E%20D%5B%22%E5%89%82%E9%87%8F%E4%B8%8A%E9%99%90%22%5D%0A%20%20B%20--%3E%20E%5B%22%E9%A2%84%E7%AE%97%E7%AA%97%E5%8F%A3%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22PEB%20%E6%94%BE%E5%A4%A7%20%2F%20SMO%20%E6%8F%90%E6%95%88%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%9C%A8%E7%BA%BF%E5%89%82%E9%87%8F%20%2B%20LER%20%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：像下雨天拍照——光少则照片全是噪点（随机缺陷），加长曝光则一天拍不了几张（产能掉）。EUV 摄影师的任务：用最高效的胶卷（化学放大）、最大的光圈（SMO），把「不糊片」所需的最短曝光时间压到最短。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"泊松机制是底层物理：胶中一个特征接收 \\(N\\) 个光子，吸收并引发酸反应的涨落 \\(\\sqrt{N}/N\\) 直接写进线边缘——CD 波动 \\(\\propto1/\\sqrt{N}\\)，剂量翻倍只降 29% 的涨落，缺陷率（对涨落的指数敏感）才降一个量级。放大机制：化学放大胶把每个光子的吸收放大成数十个酸分子的催化脱保——这是「量子增益」，但酸扩散又带进新的随机性（blur 与噪声的交换）。高 NA 的乘数效应：光子吸收在胶内更浅（更少反射损失）+ 数值孔径更大 → 同剂量下像质更好，或同像质下剂量下限更低——High-NA 的剂量经济学是它落地的核心论据之一。上游约束：光源功率（250W 级）决定每秒光子总量，剂量上限其实是光源税。",-1)),(s(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%B6%A8%E8%90%BD%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%7D%20--%3E%20R%5B%22%E6%B3%8A%E6%9D%BE%3A%20%CF%83%3D%E2%88%9AN%22%5D%0A%20%20R%20--%3E%20S%5B%22CD%20%E6%B3%A2%E5%8A%A8%20%E2%88%9D%201%2F%E2%88%9AN%22%5D%0A%20%20S%20--%3E%20T%5B%22%E7%BC%BA%E9%99%B7%E7%8E%87%E6%8C%87%E6%95%B0%E6%95%8F%E6%84%9F%20%E2%86%92%20%E5%89%82%E9%87%8F%C3%972%20%E7%BC%BA%E9%99%B7%20%C3%B710%22%5D%0A%20%20U%7B%22%E5%A2%9E%E7%9B%8A%E4%BB%8E%E5%93%AA%E6%9D%A5%3F%22%7D%20--%3E%20V%5B%22%E5%8C%96%E5%AD%A6%E6%94%BE%E5%A4%A7%3A%20%E4%B8%80%E5%85%89%E5%AD%90%E6%95%B0%E5%8D%81%E9%85%B8%22%5D%0A%20%20V%20--%3E%20W%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%20%3D%20%E6%96%B0%E9%9A%8F%E6%9C%BA%E6%BA%90%22%5D%0A%20%20X%7B%22High-NA%20%E5%B8%AE%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20Y%5B%22%E5%90%B8%E6%94%B6%E6%9B%B4%E6%B7%B1%2FNA%20%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20Y%20--%3E%20Z%5B%22%E5%90%8C%E5%83%8F%E8%B4%A8%E6%9B%B4%E4%BD%8E%E5%89%82%E9%87%8F%E4%B8%8B%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：把剂量当「越大越保险」——过高剂量让胶过曝、CD 膨胀，dose-to-size 窗口整体漂移；另一误区是把 LER 全归给剂量——胶分子尺寸、酸扩散长度与剂量各占一份，单靠加剂量压 LER 会先撞产能墙。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预算的边界条件在移动：光源功率每代提升（250W→500W+）抬高上限；胶的量子效率与灵敏度是业界「EUV resist challenge」的主战场；multi-patterning 回归（High-NA 场域减半 + SADP）则重新分配「哪些线用多少剂量」。管理上的边界：剂量-缺陷-产能的三角没有全局最优点，只有按层（关键层高剂量、非关键层省）的分层预算——与 mix-and-match 的分区逻辑同构，只是把「机器分配」换成了「光子分配」。与 stochastics 文献的接口：imec/ASML 的联合研究给出「剂量-CD-缺陷率」的经验标定，是每个新节点定义预算的起点。</p><p><span class="marginnote">直觉类比：剂量预算像「公司差旅标准」——下限是「出不了差就误事」（缺陷超标），上限是「公司现金流」（产能）；中层管理者（工艺整合）的任务是给每个部门（每层）定不同的标准，让每一块钱（每一份剂量）花在刀刃上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剂量 = 缺陷率与产能的汇率；泊松涨落 √N 是底层物理。</li><li>下限由缺陷定价、上限由光源与产能定价；PEB/SMO 提效。</li><li>分层预算：关键层高剂量、非关键层省——没有全局最优点。</li><li>出处：Poisson 光子统计基础；ASML NXE 剂量-产能数据；imec stochastics 论文（2021-2024）。</li></ul>',6))])}const N=A(p,[["render",m]]);export{C as __pageData,N as default};
